; Philips RC-6 mode 0 infrared frame with a 36 kHz carrier; one frame per host word (8 | toggle << 4 | address << 13 | command << 5), acknowledged
; Generated by escgen from protocols/rc6_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: SB-Projects, Philips RC-6 Protocol, www.sbprojects.net/knowledge/ir/rc6.php: 36 kHz carrier, duty 25% to 50%, t = 16 carrier periods = 444 us; leader 6t mark and 2t space; start bit 1; mode bits mb2..mb0 = 000 for mode 0; trailer bit 2t mark and 2t space (the toggle); a 1 is a mark then a space, a 0 a space then a mark; 8 control and 8 information bits, MSB first; 6t signal-free time
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ PERIOD, (CLK_KHZ * 10 + 180) // 360
.equ T, 16 * PERIOD
.equ FREE, 6 * T
.equ C_PERIOD, PERIOD
.equ C_HIGH, (PERIOD + 1) // 3
.default PIN_IR, 0
.equ P_IR, 1 << PIN_IR

.own  PIN_IR, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_IR, 0, P_IR               ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    LDLC  (6 * T) // C_PERIOD         ; leader: carrier pulses
    CALL  burst
    ADDT  2 * T - 64                  ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOV   r0, r1                      ; 4 bits, MSB first, each zero or one
    SHL   r0, 28                      ; the field's first bit to bit 31
    MOVI  r3, 0
bit1:
    SHL   r0, 1                       ; C = the next bit
    JC    one2
    ADDT  T                           ; zero: no change, no event
    LDLC  (T) // C_PERIOD             ; carrier pulses
    CALL  burst
    JMP   next3
one2:
    LDLC  (T) // C_PERIOD             ; one: carrier pulses
    CALL  burst
    ADDT  T                           ; no change, no event
next3:
    ADDI  r3, 1
    CMPI  r3, 4                       ; Z after the last bit
    JNZ   bit1
    SHR   r1, 4                       ; next field
    MOV   r0, r1                      ; 1 bits, MSB first, each tr0 or tr1
    SHL   r0, 31                      ; the field's first bit to bit 31
    MOVI  r3, 0
bit4:
    SHL   r0, 1                       ; C = the next bit
    JC    one5
    ADDT  2 * T - 64                  ; tr0: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    LDLC  (2 * T) // C_PERIOD         ; carrier pulses
    CALL  burst
    JMP   next6
one5:
    LDLC  (2 * T) // C_PERIOD         ; tr1: carrier pulses
    CALL  burst
    ADDT  2 * T - 64                  ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
next6:
    ADDI  r3, 1
    CMPI  r3, 1                       ; Z after the last bit
    JNZ   bit4
    SHR   r1, 1                       ; next field
    MOV   r0, r1                      ; 16 bits, MSB first, each zero or one
    SHL   r0, 16                      ; the field's first bit to bit 31
    MOVI  r3, 0
bit7:
    SHL   r0, 1                       ; C = the next bit
    JC    one8
    ADDT  T                           ; zero: no change, no event
    LDLC  (T) // C_PERIOD             ; carrier pulses
    CALL  burst
    JMP   next9
one8:
    LDLC  (T) // C_PERIOD             ; one: carrier pulses
    CALL  burst
    ADDT  T                           ; no change, no event
next9:
    ADDI  r3, 1
    CMPI  r3, 16                      ; Z after the last bit
    JNZ   bit7
    ADDT  FREE - 64                   ; free: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet

; ---- burst: lc carrier pulses from tmr; returns with tmr = start + lc * C_PERIOD
burst:
    EMIT  P_IR, P_IR, P_IR
    ADDT  C_HIGH
    EMIT  P_IR, 0, P_IR
    ADDT  C_PERIOD - C_HIGH
    DJNZ  burst
    RET
